import { View, type ViewProps } from 'react-native';

import { cn } from '@/lib/utils';

import { Text, type TextProps } from './text';

type DivProps = ViewProps & { className?: string };

export function Card({ className, ...props }: DivProps) {
  return (
    <View className={cn('rounded-xl border border-border bg-card p-4', className)} {...props} />
  );
}

export function CardHeader({ className, ...props }: DivProps) {
  return <View className={cn('mb-3 gap-1', className)} {...props} />;
}

export function CardTitle({ ...props }: TextProps) {
  return <Text className="text-xl font-semibold" {...props} />;
}

export function CardDescription({ ...props }: TextProps) {
  return <Text variant="muted" {...props} />;
}

export function CardContent({ className, ...props }: DivProps) {
  return <View className={cn('gap-2', className)} {...props} />;
}

export function CardFooter({ className, ...props }: DivProps) {
  return <View className={cn('mt-4 flex-row items-center gap-2', className)} {...props} />;
}
